/* ELF version script for libcryptolib_c (Linux/GNU ld / lld).
 * Export ONLY the C ABI (cryptolib_*); make every other symbol local, hiding
 * the statically-linked dependency symbols (liboqs, blst, …). Minimizes the
 * library's surface to exactly the intended boundary. */
CRYPTOLIB {
  global:
    cryptolib_*;
  local:
    *;
};
